def compute(panel):
    out = {}
    for c in panel.codes():
        closes = panel.closes(c)
        if len(closes) < 3:
            continue
        px = panel.close.get(c)
        base = closes[-3]
        if not px or not base:
            continue
        out[c] = round((px / base - 1) * -1, 4)
    return out

